#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int is_int; // 1 if data is int, 0 if data is string
    union {
        int data_int;
        char stringset[500];
    } data;
} D_type;

// Function to initialize N-dimensional array and return both the dimensions and
// array elements
void init_array(int n, D_type **array, int **dimensions, int *total_size) {
    int temp = 0, j = 0;
    *dimensions = (int *)malloc(n * sizeof(int));
    if (*dimensions == NULL) {
        printf("Memory allocation for dimensions failed\n");
        exit(1);
    }

    int sum = 1;
    printf("Enter the number of elements in each dimension: ");
    for (int i = 0; i < n; i++) {
        scanf("%d", &(*dimensions)[i]);
        sum *= (*dimensions)[i];
    }
    *total_size = sum;

    *array = (D_type *)malloc(sum * sizeof(D_type));
    if (*array == NULL) {
        printf("Memory allocation for array elements failed\n");
        free(*dimensions); // Free the previously allocated memory for dimensions
        exit(1);
    }

    printf("Enter the elements of the array:\n");
    for (int i = 0; i < sum; i++) {
        printf("Enter the type of data for dimension %d and %d (0 for string, 1 for int):\n", temp, j);
        if (j == (*dimensions)[temp]) {
            temp++;
            j = 0;
        } else {
            j++;
        }

        int data_type;
        scanf("%d", &data_type);

        if (data_type == 1) {
            (*array)[i].is_int = 1;
            printf("Enter the integer data: ");
            scanf("%d", &(*array)[i].data.data_int);
        } else {
            (*array)[i].is_int = 0;
            printf("Enter the string data: ");
            scanf(" %[^\n]", (*array)[i].data.stringset);
        }
    }

    printf("Your array has been initiated\n");
}

int main() {
    int n, total_size;
    int *dimensions;
    D_type *array;

    printf("Enter the number of dimensions: ");
    scanf("%d", &n);

    init_array(n, &array, &dimensions, &total_size);

    // Access and print array elements (example)
    for (int i = 0; i < total_size; i++) {
        if (array[i].is_int) {
            printf("Element %d: %d\n", i, array[i].data.data_int);
        } else {
            printf("Element %d: %s\n", i, array[i].data.stringset);
        }
    }

    free(array);
    free(dimensions);

    return 0;
}
```

